int unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                        cdf_summary_info_header_t *ssi, cdf_property_info_t **info,
                        size_t *count) {
    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    const size_t header_size = sizeof(cdf_summary_info_header_t);
    if (h->offset_summary_info + header_size > sst->size) {
        return -1;
    }

    memcpy(ssi, sst->data + h->offset_summary_info, header_size);

    if (h->byte_order != ssi->byte_order) {
        ssi->byte_order = (h->byte_order == 0xfffe) ? 0xfeff : 0xfffe;
    }

    size_t prop_count = ssi->property_count;
    if (prop_count > (size_t)(sst->size - h->offset_summary_info - header_size)) {
        return -1;
    }

    cdf_property_info_t *props = malloc(prop_count);
    if (!props) {
        return -1;
    }

    memcpy(props, sst->data + h->offset_summary_info + header_size, prop_count);
    *info = props;
    *count = prop_count;

    return 0;
}

int unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h, cdf_summary_info_header_t *ssi, cdf_property_info_t **info, size_t *count) {
    size_t i;
    size_t num_props;
    const uint8_t *data;
    size_t data_size;

    if (!sst || !h || !ssi || !info || !count)
        return -1;

    data = cdf_stream_get_data(sst, h->summary_info_offset, sizeof(cdf_summary_info_header_t));
    if (!data)
        return -1;

    memcpy(ssi, data, sizeof(cdf_summary_info_header_t));

    data_size = cdf_stream_get_size(sst, h->summary_info_offset);
    if (data_size < sizeof(cdf_summary_info_header_t))
        return -1;

    num_props = le_to_cpu16(ssi->num_properties);
    if (num_props == 0 || num_props > (data_size - sizeof(cdf_summary_info_header_t)) / sizeof(cdf_property_info_t))
        return -1;

    *info = (cdf_property_info_t *)malloc(num_props * sizeof(cdf_property_info_t));
    if (!*info)
        return -1;

    data = cdf_stream_get_data(sst, h->summary_info_offset + sizeof(cdf_summary_info_header_t), num_props * sizeof(cdf_property_info_t));
    if (!data) {
        free(*info);
        *info = NULL;
        return -1;
    }

    for (i = 0; i < num_props; i++) {
        cdf_property_info_t *prop = &(*info)[i];
        memcpy(prop, data + (i * sizeof(cdf_property_info_t)), sizeof(cdf_property_info_t));
        prop->property_id = le_to_cpu16(prop->property_id);
        prop->type = le_to_cpu16(prop->type);
        prop->offset = le_to_cpu32(prop->offset);
        prop->length = le_to_cpu32(prop->length);
    }

    *count = num_props;
    return 0;
}

int unpack_cdf_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                            cdf_summary_info_header_t *ssi, cdf_property_info_t **info,
                            size_t *count) {
    size_t i;
    size_t prop_count;

    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (sst->length < sizeof(cdf_summary_info_header_t)) {
        return -1;
    }

    ssi->byte_order = sst->byte_order;
    ssi->os_version = h->os_version;
    ssi->os_type = h->os_type;
    ssi->class_id = h->class_id;
    ssi->property_count = h->summary_property_count;

    prop_count = ssi->property_count;
    *count = prop_count;

    if (prop_count == 0) {
        *info = NULL;
        return 0;
    }

    *info = (cdf_property_info_t *)malloc(prop_count * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    for (i = 0; i < prop_count; ++i) {
        if (sst->read(sst, &(*info)[i], sizeof(cdf_property_info_t)) != sizeof(cdf_property_info_t)) {
            free(*info);
            *info = NULL;
            return -1;
        }
    }

    return 0;
}

int unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h, cdf_summary_info_header_t *ssi, cdf_property_info_t **info, size_t *count) {
    size_t i;
    size_t num_properties;

    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (sst->size < sizeof(cdf_summary_info_header_t)) {
        return -1;
    }

    ssi->byte_order = *(uint16_t *)((uint8_t *)sst->data + h->summary_info_offset);
    ssi->os_version = *(uint16_t *)((uint8_t *)sst->data + h->summary_info_offset + 2);
    ssi->os_type = *(uint16_t *)((uint8_t *)sst->data + h->summary_info_offset + 4);
    ssi->class = *(uint32_t *)((uint8_t *)sst->data + h->summary_info_offset + 6);
    num_properties = *(uint32_t *)((uint8_t *)sst->data + h->summary_info_offset + 10);

    if (num_properties > (sst->size - sizeof(cdf_summary_info_header_t)) / sizeof(cdf_property_info_t)) {
        return -1;
    }

    *info = (cdf_property_info_t *)malloc(num_properties * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    for (i = 0; i < num_properties; ++i) {
        size_t offset = h->summary_info_offset + sizeof(cdf_summary_info_header_t) + i * sizeof(cdf_property_info_t);
        if (offset + sizeof(cdf_property_info_t) > sst->size) {
            free(*info);
            *info = NULL;
            return -1;
        }
        (*info)[i].property_id = *(uint16_t *)((uint8_t *)sst->data + offset);
        (*info)[i].type = *(uint16_t *)((uint8_t *)sst->data + offset + 2);
        (*info)[i].value_length = *(uint32_t *)((uint8_t *)sst->data + offset + 4);
        (*info)[i].value_offset = *(uint32_t *)((uint8_t *)sst->data + offset + 8);
    }

    *count = num_properties;
    return 0;
}

int unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                        cdf_summary_info_header_t *ssi, cdf_property_info_t **info,
                        size_t *count) {
    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (sst->size < h->summary_info_offset || sst->size < h->property_offset) {
        return -1;
    }

    if (h->summary_info_size > sst->size - h->summary_info_offset) {
        return -1;
    }

    if (h->property_count > SIZE_MAX / sizeof(cdf_property_info_t)) {
        return -1;
    }

    if (h->property_count == 0 || h->property_offset == 0) {
        *info = NULL;
        *count = 0;
        return 0;
    }

    if (h->property_size > sst->size - h->property_offset) {
        return -1;
    }

    *info = (cdf_property_info_t *)malloc(h->property_count * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    for (size_t i = 0; i < h->property_count; ++i) {
        const uint8_t *prop_data = sst->data + h->property_offset + i * h->property_size;
        (*info)[i].property_id = *(uint32_t *)(prop_data);
        (*info)[i].type = *(uint16_t *)(prop_data + 4);
        (*info)[i].offset = *(uint32_t *)(prop_data + 6);
        (*info)[i].size = *(uint32_t *)(prop_data + 10);
    }

    *count = h->property_count;

    return 0;
}
